enum
{
	MT2009_CUBE_CAT_ARMOR, MT2009_CUBE_CAT_WEAPON, MT2009_CUBE_CAT_ACCESSORY, MT2009_CUBE_CAT_BELT, MT2009_CUBE_CAT_EVENT,
	MT2009_CUBE_CAT_ETC, MT2009_CUBE_CAT_JOB, MT2009_CUBE_CAT_SETADD_WEAPON, MT2009_CUBE_CAT_SETADD_ARMOR,
	MT2009_CUBE_CAT_SETADD_HELMET, MT2009_CUBE_CAT_PET, MT2009_CUBE_CAT_SKILL_BOOK, MT2009_CUBE_CAT_ARMOR_GLOVE,
	MT2009_CUBE_CAT_ALCHEMY, MT2009_CUBE_CAT_MAX
};
static const WORD MT2009_SEONPYEONG_VNUM = 20091;

struct SMt2009CubeImprove
{
