static int Mt2009CubeCategoryOf (const CUBE_DATA* pCube)
{
	if (pCube->category >= 0 && pCube->category < MT2009_CUBE_CAT_MAX)
		return pCube->category;
	if (pCube->set_value)
		return pCube->set_part == 1 ? MT2009_CUBE_CAT_SETADD_WEAPON : (pCube->set_part == 3 ? MT2009_CUBE_CAT_SETADD_HELMET : MT2009_CUBE_CAT_SETADD_ARMOR);
	if (pCube->reward.empty())
		return MT2009_CUBE_CAT_ETC;
	const TItemTable* pTable = ITEM_MANAGER::instance().GetTable(pCube->reward[0].vnum);
	if (!pTable)
		return MT2009_CUBE_CAT_ETC;
	switch (pTable->bType)
	{
		case ITEM_WEAPON:
			return MT2009_CUBE_CAT_WEAPON;
		case ITEM_ARMOR:
			if (pTable->bSubType == ARMOR_BODY || pTable->bSubType == ARMOR_HEAD)
				return MT2009_CUBE_CAT_ARMOR;
			if (pTable->bSubType == ARMOR_GLOVE)
				return MT2009_CUBE_CAT_ARMOR_GLOVE;
			return MT2009_CUBE_CAT_ACCESSORY;
		case ITEM_BELT:
			return MT2009_CUBE_CAT_BELT;
		case ITEM_SKILLBOOK:
			return MT2009_CUBE_CAT_SKILL_BOOK;
		case ITEM_PET:
			return MT2009_CUBE_CAT_PET;
		default:
			return MT2009_CUBE_CAT_ETC;
	}
}

static void Mt2009CubeImproveLoad ()
{
	s_mapMt2009CubeImproveTable.clear();
	char szFile[256 + 1];
	snprintf(szFile, sizeof(szFile), "%s/cube_improve.txt", LocaleService_GetBasePath().c_str());
	FILE* fp = fopen(szFile, "r");
	if (!fp)
		return;
	char szLine[256];
	while (fgets(szLine, sizeof(szLine), fp))
	{
		if (szLine[0] == '#')
			continue;
		unsigned int uVnum = 0;
		int iBonus = 0, iCategory = -1;
		char szNpc[200] = "";
		if (sscanf(szLine, "%u %d %d %199s", &uVnum, &iBonus, &iCategory, szNpc) < 3 || !uVnum || iBonus <= 0
			|| iCategory < 0 || iCategory >= MT2009_CUBE_CAT_MAX)
			continue;
		SMt2009CubeImprove kImprove;
		kImprove.iBonus = MIN(iBonus, 100);
		kImprove.iCategory = iCategory;
		for (char* p = strtok(szNpc, ","); p; p = strtok(NULL, ","))
			if (atoi(p) > 0)
				kImprove.vecNpc.push_back((DWORD)atoi(p));
		s_mapMt2009CubeImproveTable[uVnum] = kImprove;
	}
	fclose(fp);
	sys_log(0, "cube_improve: %u chance-raising items", (unsigned int)s_mapMt2009CubeImproveTable.size());
}

// Seon-Pyeong's rows: every item whose refine set is an elite one (constants.cpp IsEliteRefine) - once a load
static void Mt2009CubeSynthElite ()
{
	for (size_t i = 0; i < s_cube_proto.size(); ++i)
		if (s_cube_proto[i]->copy_attr == 2)
			return;
	const std::vector<TItemTable>& rkTables = ITEM_MANAGER::instance().GetTable();
	size_t uMade = 0;
	for (size_t i = 0; i < rkTables.size(); ++i)
	{
		const TItemTable& t = rkTables[i];
		if (!t.dwRefinedVnum || !IsEliteRefine(t.wRefineSet) || !ITEM_MANAGER::instance().GetTable(t.dwRefinedVnum))
			continue;
		const TRefineTable* pRefine = CRefineManager::instance().GetRefineRecipe(t.wRefineSet);
		if (!pRefine)
			continue;
		CUBE_DATA* pCube = M2_NEW CUBE_DATA;
		pCube->npc_vnum.emplace_back(MT2009_SEONPYEONG_VNUM);
		CUBE_VALUE kValue = {t.dwVnum, 1};
		pCube->item.emplace_back(kValue);
		for (int j = 0; j < pRefine->material_count && j < REFINE_MATERIAL_MAX_NUM; ++j)
		{
			if (!pRefine->materials[j].vnum || (int)pRefine->materials[j].count <= 0)
				continue;
			CUBE_VALUE kMaterial = {pRefine->materials[j].vnum, (int)pRefine->materials[j].count};
			pCube->item.emplace_back(kMaterial);
		}
		CUBE_VALUE kReward = {t.dwRefinedVnum, 1};
		pCube->reward.emplace_back(kReward);
		pCube->percent = pRefine->prob;
		pCube->gold = pRefine->cost;
		pCube->copy_attr = 2;
		s_cube_proto.emplace_back(pCube);
		++uMade;
	}
	sys_log(0, "cube: %u Seon-Pyeong rows from the elite refine sets", (unsigned int)uMade);
}

