static CUBE_DATA* Mt2009CubeFindPicked (LPCHARACTER ch, LPITEM *items, WORD npc_vnum)
{
	std::map<DWORD, DWORD>::const_iterator it = s_mapMt2009CubePick.find(ch->GetPlayerID());
	if (it != s_mapMt2009CubePick.end())
	{
		for (size_t i = 0; i < s_cube_proto.size(); ++i)
		{
			CUBE_DATA* pCube = s_cube_proto[i];
			if (1 == pCube->reward.size() && pCube->reward[0].vnum == it->second && pCube->can_make_item(items, npc_vnum))
				return pCube;
		}
	}
	return FN_find_cube(items, npc_vnum);
}

// the chance-raising item the player put in the window, if it works on this recipe at this NPC
static LPITEM Mt2009CubeImproveItem (LPCHARACTER ch, const CUBE_DATA* pCube, WORD wNpc, int* piBonus)
{
	*piBonus = 0;
	std::map<DWORD, DWORD>::const_iterator it = s_mapMt2009CubeImprove.find(ch->GetPlayerID());
	if (it == s_mapMt2009CubeImprove.end())
		return NULL;
	LPITEM pItem = ch->FindItemByID(it->second);
	if (!pItem || pItem->GetOwner() != ch || pItem->IsEquipped())
		return NULL;
	std::map<DWORD, SMt2009CubeImprove>::const_iterator itTable = s_mapMt2009CubeImproveTable.find(pItem->GetVnum());
	if (itTable == s_mapMt2009CubeImproveTable.end() || itTable->second.iCategory != Mt2009CubeCategoryOf(pCube))
		return NULL;
	const std::vector<DWORD>& rvecNpc = itTable->second.vecNpc;
	if (!rvecNpc.empty() && std::find(rvecNpc.begin(), rvecNpc.end(), (DWORD)wNpc) == rvecNpc.end())
		return NULL;
	*piBonus = itTable->second.iBonus;
	return pItem;
}

void Cube_improve (LPCHARACTER ch, int iInvenPos)
{
	if (NULL == ch || !ch->IsCubeOpen())
		return;
	LPITEM pItem = (iInvenPos >= 0 && iInvenPos < INVENTORY_DEFAULT_MAX_NUM) ? ch->GetInventoryItem(iInvenPos) : NULL;
	std::map<DWORD, SMt2009CubeImprove>::const_iterator it = pItem ? s_mapMt2009CubeImproveTable.find(pItem->GetVnum()) : s_mapMt2009CubeImproveTable.end();
	if (!pItem || it == s_mapMt2009CubeImproveTable.end())
	{
		s_mapMt2009CubeImprove.erase(ch->GetPlayerID());
		if (pItem)
			ch->ChatPacket(CHAT_TYPE_INFO, "Ten przedmiot nie zwi\352ksza szansy wytwarzania.");
		ch->ChatPacket(CHAT_TYPE_COMMAND, "CubeImprove 0 0 -1");
		return;
	}
	s_mapMt2009CubeImprove[ch->GetPlayerID()] = pItem->GetID();
	ch->ChatPacket(CHAT_TYPE_COMMAND, "CubeImprove %u %d %d", pItem->GetVnum(), it->second.iBonus, it->second.iCategory);
}

// a recipe whose result takes the first item's stones and bonuses (copy_attr; Seon-Pyeong, Admiral Angmur)
static bool Mt2009CubeMakeCopy (LPCHARACTER ch, CUBE_DATA* cube_proto, CUBE_VALUE* reward_value)
{
	LPITEM* items = ch->GetCubeItem();
	if (!Mt2009GayaCubeCheck(ch, cube_proto))
		return false;
	LPITEM pSource = NULL;
	for (int i = 0; i < CUBE_MAX_NUM && !pSource && !cube_proto->item.empty(); ++i)
		if (items[i] && items[i]->GetVnum() == cube_proto->item[0].vnum)
			pSource = items[i];
	LPITEM pNew = pSource ? ITEM_MANAGER::instance().CreateItem(reward_value->vnum, reward_value->count, 0, false) : NULL;
	if (!pNew)
	{
		ch->ChatPacket(CHAT_TYPE_INFO, LC_TEXT("You do not have the right material."));
		return false;
	}
	ITEM_MANAGER::CopyAllAttrTo(pSource, pNew);
	cube_proto->remove_material(ch);
	Mt2009GayaCubeTake(ch, cube_proto);
	if (0 < cube_proto->gold)
		ch->ChangeGold(-(cube_proto->gold));
	if (number(1, 100) <= cube_proto->percent)
	{
		const DWORD dwNewId = pNew->GetID();
		ch->ChatPacket(CHAT_TYPE_COMMAND, "cube success %d %d", reward_value->vnum, reward_value->count);
		ch->AutoGiveItem(pNew);
		LogManager::instance().CubeLog(ch->GetPlayerID(), ch->GetX(), ch->GetY(), reward_value->vnum, dwNewId, reward_value->count, 1);
		return true;
	}
	M2_DESTROY_ITEM(pNew);
	ch->ChatPacket(CHAT_TYPE_INFO, LC_TEXT("Failed to craft."));
	ch->ChatPacket(CHAT_TYPE_COMMAND, "cube fail");
	LogManager::instance().CubeLog(ch->GetPlayerID(), ch->GetX(), ch->GetY(), reward_value->vnum, 0, 0, 0);
	return false;
}

static int Mt2009CubeWindowWeight (LPITEM* items)
{
	int iWeight = 0;
	for (int i = 0; i < CUBE_MAX_NUM; ++i)
		if (items[i])
			iWeight += 1 + (int)items[i]->GetCount();
	return iWeight;
}

// "cube make" of the window: the chance-raising item's bonus for this attempt (the recipe's chance is raised for the
// one Cube_make and set back), one piece of it goes when the attempt took the materials
bool Cube_make_window (LPCHARACTER ch)
{
	if (NULL == ch || !ch->IsCubeOpen())
		return Cube_make(ch);
	LPCHARACTER npc = ch->GetQuestNPC();
	if (NULL == npc)
		return Cube_make(ch);
	LPITEM* items = ch->GetCubeItem();
	CUBE_DATA* pCube = Mt2009CubeFindPicked(ch, items, npc->GetRaceNum());
	int iBonus = 0;
	LPITEM pImprove = pCube ? Mt2009CubeImproveItem(ch, pCube, npc->GetRaceNum(), &iBonus) : NULL;
	if (!pImprove || iBonus <= 0 || pCube->percent >= 100)
		return Cube_make(ch);
	const DWORD dwImproveId = pImprove->GetID();
	const int iSavedPercent = pCube->percent;
	const int iWeightBefore = Mt2009CubeWindowWeight(items);
	pCube->percent = MIN(100, iSavedPercent + iBonus);
	const bool bResult = Cube_make(ch);
	pCube->percent = iSavedPercent;
	if (Mt2009CubeWindowWeight(ch->GetCubeItem()) != iWeightBefore)
	{
		LPITEM pUsed = ch->FindItemByID(dwImproveId);
		if (pUsed)
			pUsed->SetCount(pUsed->GetCount() - 1);
		ch->ChatPacket(CHAT_TYPE_INFO, "Szansa podwy\277szona o %d%% (zu\277yto 1 przedmiot).", iBonus);
	}
	return bResult;
}

